expect.extend({
  toBeWithin(received: number, min: number, max: number) {
    const pass = received >= min && received <= max;
    return {
      pass,
      message: () =>
        `expected ${received} ${pass ? "not " : ""}to be within ${min} and ${max}`,
    };
  },
});

test("supports a domain-specific expectation", () => {
  expect(7).toBeWithin(5, 10);
});

test('matches exact, structural, partial, and thrown values', () => {
  const result = {id: 7, name: 'Ada'};
  expect(result.id).toBe(7);
  expect(result).toEqual({id: 7, name: 'Ada'});
  expect(result).toMatchObject({name: 'Ada'});
  expect(() => { throw new Error('bad input'); }).toThrow('bad input');
});

test("serializes the result", () => {
  const result = {status: "ok", count: 2};

  expect(result).toMatchSnapshot();
});

describe('expiration', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2024-01-01T00:00:00Z'));
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test('runs after one hour', () => {
    const callback = jest.fn();
    setTimeout(callback, 60 * 60 * 1000);

    jest.advanceTimersByTime(60 * 60 * 1000);

    expect(callback).toHaveBeenCalledTimes(1);
  });
});

test('rejects with an error', async () => {
  await expect(Promise.reject(new Error('octopus'))).rejects.toThrow('octopus');
});

