import { jest, test, expect, afterEach } from '@jest/globals';

const api = {
  fetchUser: (id: string) => `user-${id}`,
};

afterEach(() => {
  jest.restoreAllMocks();
});

test('spies while using a temporary implementation', () => {
  const fetchUser = jest
    .spyOn(api, 'fetchUser')
    .mockImplementation((id: string) => `stub-${id}`);

  expect(api.fetchUser('42')).toBe('stub-42');
  expect(fetchUser).toHaveBeenCalledWith('42');
});

